From a29e455d8ed892339576f0ea6a06e1f0e5e454d2 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 28 Nov 2026 12:28:41 +0100
Subject: [PATCH] kcms/activities: add option to ignore apps preventing sleep

Apps that ask to keep the system awake always stopped it from sleeping,
with no way to opt out per activity. A new "Apps preventing sleep" box
lets an activity ignore those requests when it allows sleeping itself.

BUG: 345115
---
 kcms/activities/activityconfig.cpp    | 9 +++++++++
 kcms/activities/activityconfig.h      | 3 +++
 kcms/activities/ui/ActivityEditor.qml | 7 +++++++
 3 files changed, 19 insertions(+)

diff --git a/kcms/activities/activityconfig.cpp b/kcms/activities/activityconfig.cpp
index 1441cd5c40..ae7fde3454 100644
--- a/kcms/activities/activityconfig.cpp
+++ b/kcms/activities/activityconfig.cpp
@@ -38,6 +38,7 @@ void ActivityConfig::reset()
     m_shortcut = QKeySequence();
     m_inhibitScreen = false;
     m_inhibitSleep = false;
+    m_ignoreAppSleepInhibitions = false;
 }

 QString ActivityConfig::activityId() const
@@ -83,6 +84,10 @@ bool ActivityConfig::isSaveNeeded()
         return true;
     }

+    if (m_ignoreAppSleepInhibitions != m_savedIgnoreAppSleepInhibitions) {
+        return true;
+    }
+
     return false;
 }

@@ -129,6 +134,8 @@ void ActivityConfig::load()
     m_savedInhibitScreen = m_inhibitScreen;
     m_inhibitSleep = activityGroup.readEntry("InhibitSuspend", false);
     m_savedInhibitSleep = m_inhibitSleep;
+    m_ignoreAppSleepInhibitions = activityGroup.readEntry("IgnoreAppSuspendInhibitions", false);
+    m_savedIgnoreAppSleepInhibitions = m_ignoreAppSleepInhibitions;

     Q_EMIT infoChanged();
 }
@@ -169,6 +176,8 @@ void ActivityConfig::save()
     m_savedInhibitScreen = m_inhibitScreen;
     activityGroup.writeEntry("InhibitSuspend", m_inhibitSleep);
     m_savedInhibitSleep = m_inhibitSleep;
+    activityGroup.writeEntry("IgnoreAppSuspendInhibitions", m_ignoreAppSleepInhibitions);
+    m_savedIgnoreAppSleepInhibitions = m_ignoreAppSleepInhibitions;
 }

 void ActivityConfig::createActivity()
diff --git a/kcms/activities/activityconfig.h b/kcms/activities/activityconfig.h
index 74e739391f..147f975e61 100644
--- a/kcms/activities/activityconfig.h
+++ b/kcms/activities/activityconfig.h
@@ -25,6 +25,7 @@ class ActivityConfig : public QObject
     Q_PROPERTY(bool isSaveNeeded READ isSaveNeeded NOTIFY infoChanged)
     Q_PROPERTY(bool inhibitScreen MEMBER m_inhibitScreen NOTIFY infoChanged)
     Q_PROPERTY(bool inhibitSleep MEMBER m_inhibitSleep NOTIFY infoChanged)
+    Q_PROPERTY(bool ignoreAppSleepInhibitions MEMBER m_ignoreAppSleepInhibitions NOTIFY infoChanged)

 public:
     explicit ActivityConfig(QObject *parent = nullptr);
@@ -59,6 +60,8 @@ private:
     bool m_savedInhibitScreen = false;
     bool m_inhibitSleep = false;
     bool m_savedInhibitSleep = false;
+    bool m_ignoreAppSleepInhibitions = false;
+    bool m_savedIgnoreAppSleepInhibitions = false;

     KActivities::Controller m_activities;
     bool m_savedPrivate = false;
diff --git a/kcms/activities/ui/ActivityEditor.qml b/kcms/activities/ui/ActivityEditor.qml
index d822a799f1..ad4531f265 100644
--- a/kcms/activities/ui/ActivityEditor.qml
+++ b/kcms/activities/ui/ActivityEditor.qml
@@ -99,6 +99,13 @@ KCM.SimpleKCM {
             onToggled: settings.inhibitSleep = !checked
         }

+        QQC2.CheckBox {
+            text: i18nc("@option:check While on activity, allow", "Apps preventing sleep")
+            enabled: !settings.inhibitScreen && !settings.inhibitSleep
+            checked: !settings.ignoreAppSleepInhibitions
+            onToggled: settings.ignoreAppSleepInhibitions = !checked
+        }
+
         KQuickControls.KeySequenceItem {
             Kirigami.FormData.label: i18nc("@label prefix for keyboard shortcut input button", "Shortcut for switching:")
             keySequence: settings.shortcut
-- 
2.53.0

From 6cbcd8b85a8cda63515eada9cfccc3e6b849a909 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 28 Nov 2026 12:28:40 +0100
Subject: [PATCH] daemon: allow activities to ignore apps' sleep inhibitions

An activity could only add its own inhibitions, so an app asking to keep
the system awake always kept it from sleeping, even in an activity meant
to sleep after a while. Activities can now ignore apps' sleep requests.

BUG: 345115
---
 PowerDevilActivitySettings.kcfg  |  3 +++
 daemon/powerdevilcore.cpp        |  5 +++++
 daemon/powerdevilpolicyagent.cpp | 19 +++++++++++++++++--
 daemon/powerdevilpolicyagent.h   |  4 ++++
 4 files changed, 29 insertions(+), 2 deletions(-)

diff --git a/PowerDevilActivitySettings.kcfg b/PowerDevilActivitySettings.kcfg
index ff5f9f843..91dbbcc33 100644
--- a/PowerDevilActivitySettings.kcfg
+++ b/PowerDevilActivitySettings.kcfg
@@ -22,5 +22,8 @@ SPDX-License-Identifier: CC0-1.0
         <entry name="InhibitSuspend" type="Bool">
             <default>false</default>
         </entry>
+        <entry name="IgnoreAppSuspendInhibitions" type="Bool">
+            <default>false</default>
+        </entry>
     </group>
 </kcfg>
diff --git a/daemon/powerdevilcore.cpp b/daemon/powerdevilcore.cpp
index 33badced8..bfdebf21e 100644
--- a/daemon/powerdevilcore.cpp
+++ b/daemon/powerdevilcore.cpp
@@ -383,6 +383,7 @@ void Core::loadProfile(bool force)
     const QString activity = m_activityConsumer->currentActivity();
     qCDebug(POWERDEVIL) << "Currently using activity" << activity;

+    bool ignoreSuspendInhibitions = false;
     if (!activity.isEmpty()) {
         PowerDevil::ActivitySettings activitySettings(activity);

@@ -414,7 +415,11 @@ void Core::loadProfile(bool force)
                 m_screenActivityInhibit.insert(activity, cookie);
             }
         }
+        // The activity's own inhibitions also block sleep, so only ignore apps' ones when it has none
+        ignoreSuspendInhibitions =
+            activitySettings.ignoreAppSuspendInhibitions() && !activitySettings.inhibitSuspend() && !activitySettings.inhibitScreenManagement();
     }
+    PolicyAgent::instance()->setIgnoreSuspendInhibitions(ignoreSuspendInhibitions);

     // If the lid is closed, retrigger the lid close signal
     // so that "switching profile then closing the lid" has the same result as
diff --git a/daemon/powerdevilpolicyagent.cpp b/daemon/powerdevilpolicyagent.cpp
index 8ed1edc60..3065e5f1a 100644
--- a/daemon/powerdevilpolicyagent.cpp
+++ b/daemon/powerdevilpolicyagent.cpp
@@ -534,7 +534,7 @@ PolicyAgent::RequiredPolicies PolicyAgent::unavailablePolicies()
     if (!m_screenLockerActive && !m_typesToCookie[ChangeScreenSettings].isEmpty()) {
         retpolicies |= ChangeScreenSettings;
     }
-    if (!m_typesToCookie[InterruptSession].isEmpty()) {
+    if (!m_ignoreSuspendInhibitions && !m_typesToCookie[InterruptSession].isEmpty()) {
         retpolicies |= InterruptSession;
     }

@@ -546,6 +546,21 @@ bool PolicyAgent::screenLockerActive() const
     return m_screenLockerActive;
 }

+void PolicyAgent::setIgnoreSuspendInhibitions(bool ignore)
+{
+    if (m_ignoreSuspendInhibitions == ignore) {
+        return;
+    }
+
+    const auto oldPolicies = unavailablePolicies();
+    m_ignoreSuspendInhibitions = ignore;
+    const auto newPolicies = unavailablePolicies();
+
+    if (oldPolicies != newPolicies) {
+        Q_EMIT unavailablePoliciesChanged(newPolicies);
+    }
+}
+
 PolicyAgent::RequiredPolicies PolicyAgent::requirePolicyCheck(PolicyAgent::RequiredPolicies policies)
 {
     if (!m_sdAvailable) {
@@ -580,7 +595,7 @@ PolicyAgent::RequiredPolicies PolicyAgent::requirePolicyCheck(PolicyAgent::Requi
         }
     }
     if (policies & InterruptSession) {
-        if (m_sessionIsBeingInterrupted || !m_typesToCookie[InterruptSession].isEmpty()) {
+        if (m_sessionIsBeingInterrupted || (!m_ignoreSuspendInhibitions && !m_typesToCookie[InterruptSession].isEmpty())) {
             retpolicies |= InterruptSession;
         }
     }
diff --git a/daemon/powerdevilpolicyagent.h b/daemon/powerdevilpolicyagent.h
index 41c8b45d9..13800067b 100644
--- a/daemon/powerdevilpolicyagent.h
+++ b/daemon/powerdevilpolicyagent.h
@@ -101,6 +101,8 @@ public:

     bool screenLockerActive() const;

+    void setIgnoreSuspendInhibitions(bool ignore);
+
     void setupSystemdInhibition();

     // DEPRECATED: D-Bus getter method, returns array of {who, why}. Use properties instead
@@ -182,6 +184,8 @@ private:
     QPointer<QDBusInterface> m_ckSeatInterface;
     bool m_sessionIsBeingInterrupted;

+    bool m_ignoreSuspendInhibitions = false;
+
     QHash<uint, InhibitionInternals> m_cookieToInhibition;
     QHash<uint, QString> m_cookieToBusService;
     QHash<RequiredPolicy, QList<uint>> m_typesToCookie;
-- 
2.53.0
